from operator import itemgetter
import sys


def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    n = int(data[0])
    pts = []
    idx = 1
    for _ in range(n):
        pts.append((int(data[idx]), int(data[idx + 1])))
        idx += 2

    pts.sort()
    for i in range(n - 1):
        if pts[i] == pts[i + 1]:
            sys.stdout.write("0\n")
            return

    key_y = itemgetter(1)

    def dc(l: int, r: int) -> tuple[int, list[tuple[int, int]]]:
        if r - l <= 16:
            sub = pts[l:r]
            best = (sub[0][0] - sub[1][0]) ** 2 + (sub[0][1] - sub[1][1]) ** 2
            m = len(sub)
            for i in range(m):
                xi, yi = sub[i]
                for j in range(i + 1, m):
                    dx = xi - sub[j][0]
                    dy = yi - sub[j][1]
                    d2 = dx * dx + dy * dy
                    if d2 < best:
                        best = d2
            sub.sort(key=key_y)
            return best, sub

        mid = (l + r) // 2
        mid_x = pts[mid][0]
        d1, ly = dc(l, mid)
        d2, ry = dc(mid, r)
        d = d1 if d1 < d2 else d2

        py = ly + ry
        py.sort(key=key_y)

        strip = [p for p in py if (p[0] - mid_x) ** 2 < d]
        m = len(strip)
        for i in range(m):
            xi, yi = strip[i]
            for j in range(i + 1, m):
                dy = strip[j][1] - yi
                if dy * dy >= d:
                    break
                dx = strip[j][0] - xi
                cand = dx * dx + dy * dy
                if cand < d:
                    d = cand
        return d, py

    ans, _ = dc(0, n)
    sys.stdout.write(f"{ans}\n")


