            if ((i & 1) == 0) evenXor ^= a;
        }

        bool misereFirst = allLeOne ? (allXor == 0) : (allXor != 0);
        bool stairFirst = (evenXor != 0);

        cout << (misereFirst ? "FIRST" : "SECOND") << ' '
             << (stairFirst ? "FIRST" : "SECOND") << '\n';
    }
    return 0;
}
